package com.tencent.ttsv2;

import com.google.gson.annotations.SerializedName;

/**
 * TextToStreamAudioWSV2 response.
 */
public class FlowingSpeechSynthesizerResponse {

    /**
     * Unique id of the audio stream, generated by the client during the handshake phase and set in the request parameters.
     */
    @SerializedName("session_id")
    private String sessionId;
    /**
     * Status code. 0 indicates success; a non-zero value indicates an error.
     * Client errors
     * Code   Description
     * 10001  Invalid parameter; refer to the message field for details.
     * 10002  The concurrent call quota of the current account has been exceeded.
     * 10003  Authentication failed.
     * 10004  Client data upload timeout.
     * 10005  Client connection disconnected.
     * 10006  The streaming input text contains SSML.
     * 10007  The streaming input text exceeds the maximum length limit.
     * 10008  The streaming input text channel has been closed.
     * 10009  The streaming input text was not sent before the timeout; the server will close the connection normally after synthesis is completed.
     * Server errors
     * Code   Description
     * 20000  Backend error.
     * 20001  Backend service processing failed.
     * 20002  Backend engine synthesis failed.
     * 20003  Backend engine synthesis timed out.
     */
    @SerializedName("code")
    private Integer code;
    /**
     * When this field is 1, it indicates that the synthesis of all text has finished. The client should proactively close the WebSocket connection upon receiving it.
     */
    @SerializedName("final")
    private Integer end;

    @SerializedName("ready")
    private Integer ready;
    /**
     * Error description. When an error occurs, this shows the specific cause. As the service evolves or the experience is optimized, this text may be changed or updated frequently.
     */
    @SerializedName("message")
    private String message;
    /**
     * Unique id of the audio stream, automatically generated by the server during the handshake phase.
     */
    @SerializedName("request_id")
    private String requestId;
    /**
     * Unique id of the current message.
     */
    @SerializedName("message_id")
    private String messageId;
    /**
     * The latest speech synthesis text result.
     */
    @SerializedName("result")
    private SpeechSynthesizerResult result;

    public String getSessionId() {
        return sessionId;
    }

    public void setSessionId(String sessionId) {
        this.sessionId = sessionId;
    }

    public Integer getCode() {
        return code;
    }

    public void setCode(Integer code) {
        this.code = code;
    }

    public Integer getEnd() {
        return end;
    }

    public void setEnd(Integer end) {
        this.end = end;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getMessageId() {
        return messageId;
    }

    public void setMessageId(String messageId) {
        this.messageId = messageId;
    }

    public SpeechSynthesizerResult getResult() {
        return result;
    }

    public void setResult(SpeechSynthesizerResult result) {
        this.result = result;
    }

    public Integer getReady() {
        return ready;
    }

    public void setReady(Integer ready) {
        this.ready = ready;
    }
}
